// ════════════════════════════════════════
// LÓGICA DE ÁUDIO ESTRATÉGICO
// Áudio só quando: último bloco + conversa com rapport (3+ trocas)
// + resposta não muito curta (>15 palavras) + não é link/técnico
// ════════════════════════════════════════

const item = items[0].json;
const mensagem = item.message || '';
const isLast = item.is_last === true;
const palavras = mensagem.split(' ').length;

// Conta trocas no histórico (simplificado via tamanho estimado)
// Em produção: buscar no Redis a contagem real de mensagens
const historicoEstimado = parseInt(item.sequence_index || 0);

// Condições para enviar áudio:
// 1. É o último bloco da resposta
// 2. Mensagem tem substância (>15 palavras)
// 3. Não contém links (http) — áudio com link fica estranho
// 4. Não é resposta técnica com código
// 5. Probabilidade 40% (não toda resposta vira áudio — seria excessivo)
const temLink = mensagem.includes('http') || mensagem.includes('buy.stripe');
const temCodigo = mensagem.includes('```') || mensagem.includes('//');
const temSubstancia = palavras >= 15;
const chance = Math.random() < 0.40; // 40% das vezes

const deveUsarAudio = isLast && temSubstancia && !temLink && !temCodigo && chance;

return [{
  json: {
    ...item,
    usar_audio: deveUsarAudio,
    audio_text: deveUsarAudio ? mensagem : null
  }
}];

// ════════════════════════════════════════
// QUEBRA NATURAL DE MENSAGENS — Brann v2
// Simula como humano quebraria a mensagem
// ════════════════════════════════════════

const MAX_CHARS = 280; // WhatsApp confortável
const allOutputs = [];

for (const item of items) {
  const text = (item.json.text || item.json.message || '').trim();
  const instance = item.json.instance;
  const remoteJid = item.json.remoteJid;

  if (!text) {
    allOutputs.push(item);
    continue;
  }

  // ── Estratégia de quebra em ordem de prioridade ──
  let blocos = [];

  // 1. Já tem quebras duplas (parágrafos)? Usa isso primeiro
  const porParagrafo = text.split(/\n{2,}/).map(b => b.trim()).filter(Boolean);

  if (porParagrafo.length > 1) {
    blocos = porParagrafo;
  } else {
    // 2. Quebra por frases naturais se muito longo
    if (text.length > MAX_CHARS) {
      const sentenceBreaks = text.split(/(?<=[.!?])\s+(?=[A-ZÁÉÍÓÚÂÊÔÃÕÇ])/);
      let current = '';
      for (const sentence of sentenceBreaks) {
        if ((current + ' ' + sentence).trim().length > MAX_CHARS && current.length > 0) {
          blocos.push(current.trim());
          current = sentence;
        } else {
          current = current ? current + ' ' + sentence : sentence;
        }
      }
      if (current.trim()) blocos.push(current.trim());
    } else {
      blocos = [text];
    }
  }

  // 3. Garante que nenhum bloco exceda MAX_CHARS (fallback hard)
  const finalBlocos = [];
  for (const bloco of blocos) {
    if (bloco.length <= MAX_CHARS) {
      finalBlocos.push(bloco);
    } else {
      let remaining = bloco;
      while (remaining.length > MAX_CHARS) {
        let cutAt = remaining.lastIndexOf(' ', MAX_CHARS);
        if (cutAt < MAX_CHARS * 0.5) cutAt = MAX_CHARS;
        finalBlocos.push(remaining.slice(0, cutAt).trim());
        remaining = remaining.slice(cutAt).trim();
      }
      if (remaining) finalBlocos.push(remaining);
    }
  }

  // ── Calcula delay de digitação por bloco ──
  for (let i = 0; i < finalBlocos.length; i++) {
    const palavras = finalBlocos[i].split(' ').length;
    // Humano digita ~45 palavras/min com pausas naturais
    // Delay entre 1.5s (curto) e 10s (longo), com aleatoriedade leve
    const baseDelay = Math.min(Math.max(palavras * 0.9, 1500), 10000);
    const jitter = Math.floor(Math.random() * 800); // ±800ms de variação
    const delay = Math.floor(baseDelay + jitter);

    allOutputs.push({
      json: {
        message: finalBlocos[i],
        sequence_index: i,
        total_messages: finalBlocos.length,
        is_last: i === finalBlocos.length - 1,
        instance,
        remoteJid,
        typing_delay: delay
      }
    });
  }
}

return allOutputs;
